-- Demo shop for the pilot: the Session 6 sample data (fictional shop, masked phone numbers).
-- Run after 0001_schema.sql, in the Supabase SQL editor. Dates are as in the workbook (27 Sep to 26 Oct 2026).
-- Stock in the items table is already the closing stock, so sales are loaded with the stock trigger switched off.
alter table sales disable trigger sale_reduces_stock;
alter table sales enable trigger sale_reduces_stock;

